// ============================================================================
// WintonCoin - Página Love List (Lista de Morosos)
// ============================================================================

import { getApiUrl } from '../modules/index.js';

function initializeLovePage() {
    const token = localStorage.getItem('token');
    if (!token) {
        window.location.href = 'index.html';
        return;
    }

    const tableBody = document.getElementById('love-table-body');
    const loadingSpinner = document.getElementById('loading');

    async function fetchOverdueDebts() {
        loadingSpinner.style.display = 'block';
        tableBody.innerHTML = '';

        try {
            const API_URL = getApiUrl();
            const response = await fetch(`${API_URL}/api/love-list`);

            if (!response.ok) {
                throw new Error('Error al obtener los datos del servidor.');
            }

            const data = await response.json();
            
            if (data.length === 0) {
                tableBody.innerHTML = '<tr class="love-empty-row"><td colspan="4">No hay obligaciones vencidas en este momento. ¡Felicidades a la comunidad!</td></tr>';
            } else {
                populateTable(data);
            }

        } catch (error) {
            console.error('Error:', error);
            tableBody.innerHTML = '<tr class="love-empty-row"><td colspan="4">No se pudo cargar la información. Inténtelo de nuevo más tarde.</td></tr>';
        } finally {
            loadingSpinner.style.display = 'none';
        }
    }

    function populateTable(debts) {
        debts.forEach(debt => {
            const row = document.createElement('tr');

            const overdueDate = new Date(debt.overdue_since).toLocaleDateString('es-ES', {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });

            row.innerHTML = `
                <td data-label="Usuario">${debt.username}</td>
                <td data-label="Compromiso Vencido (RED)">${parseFloat(debt.total_overdue_amount).toFixed(4)}</td>
                <td data-label="Vencido Desde">${overdueDate}</td>
                <td data-label="Reincidencias">${debt.recurrence_count}</td>
            `;
            tableBody.appendChild(row);
        });
    }

    fetchOverdueDebts();
}

// Inicializar cuando el DOM esté listo
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeLovePage);
} else {
    initializeLovePage();
}

export { initializeLovePage };
